-- ============================================================
-- PASSO 2 - FOTOGRAFIA DEL DATABASE DI DESTINAZIONE (suncity)
-- SOLA LETTURA: nessuna scrittura, nessun lock. Da eseguire nella
-- finestra psql di VS Code sul tenant SQLALCHEMY_DATABASE_URI1.
-- ============================================================

-- A) Conteggi generali
SELECT 'clienti totali'            AS voce, COUNT(*)::text AS valore FROM clienti WHERE is_deleted = false
UNION ALL SELECT 'clienti (inclusi cancellati)', COUNT(*)::text FROM clienti
UNION ALL SELECT 'pacchetti PREPAGATA',          COUNT(*)::text FROM pacchetti WHERE tipo = 'prepagata'
UNION ALL SELECT '  di cui Attivo',              COUNT(*)::text FROM pacchetti WHERE tipo = 'prepagata' AND status = 'Attivo'
UNION ALL SELECT '  con numero_tessera',         COUNT(*)::text FROM pacchetti WHERE tipo = 'prepagata' AND numero_tessera IS NOT NULL
UNION ALL SELECT 'movimenti_prepagata',          COUNT(*)::text FROM movimenti_prepagata
UNION ALL SELECT 'somma credito_residuo attivi', COALESCE(SUM(credito_residuo),0)::text
     FROM pacchetti WHERE tipo = 'prepagata' AND status = 'Attivo';

-- B) Numeri di tessera gia' assegnati
SELECT numero_tessera, id AS pacchetto_id, client_id, credito_residuo, status, data_sottoscrizione
FROM pacchetti
WHERE tipo = 'prepagata' AND numero_tessera IS NOT NULL
ORDER BY numero_tessera;

-- C) L'ipotesi "numero_tessera == cliente.id di suncity" regge?
--    432 id presenti nel .db, range 15-446.
SELECT
  COUNT(*)                                                              AS tessere_totali,
  COUNT(*) FILTER (WHERE numero_tessera ~ '^[0-9]+$')                   AS tessere_numeriche,
  COUNT(*) FILTER (WHERE numero_tessera ~ '^[0-9]+$'
                     AND numero_tessera::int BETWEEN 15 AND 446) AS nel_range_suncity
FROM pacchetti
WHERE tipo = 'prepagata' AND numero_tessera IS NOT NULL;

