tosca AS (
  SELECT id, cliente_nome, cliente_cognome,
         regexp_replace(regexp_replace(COALESCE(cliente_cellulare,''), '\D', '', 'g'),
                        '^(0039|39)(?=\d{9,10}$)', '') AS tel
  FROM clienti WHERE is_deleted = false
)
SELECT 'cellulari suncity confrontati' AS voce, COUNT(*)::text AS valore FROM suncity
UNION ALL SELECT 'gia presenti in Tosca',        COUNT(DISTINCT s.tel)::text
     FROM suncity s JOIN tosca t ON t.tel = s.tel
UNION ALL SELECT 'di cui con prepagata attiva',  COUNT(DISTINCT s.tel)::text
     FROM suncity s JOIN tosca t ON t.tel = s.tel
     JOIN pacchetti p ON p.client_id = t.id AND p.tipo = 'prepagata' AND p.status = 'Attivo';

