SELECT t.id, t.cliente_nome, t.cliente_cognome, t.tel,
       p.id AS pacchetto_id, p.numero_tessera, p.credito_residuo, p.status
FROM suncity s
JOIN tosca t ON t.tel = s.tel
LEFT JOIN pacchetti p ON p.client_id = t.id AND p.tipo = 'prepagata'
ORDER BY t.cliente_cognome, t.cliente_nome;
